  "inlineSchema": "generator client {\n  provider        = \"prisma-client-js\"\n  output          = \"../src/generated/prisma\"\n  previewFeatures = [\"driverAdapters\"]\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel Project {\n  id             String   @id @default(cuid())\n  slug           String   @unique\n  name           String\n  tagline        String?\n  location       String\n  type           String // Plots | Villas | Apartments | Commercial\n  status         String // Ongoing | Completed | Upcoming\n  price          String // display string e.g. \"₹14.5 Lacs onwards\"\n  landArea       String?\n  totalUnits     String?\n  unitSizes      String?\n  reraNumber     String?\n  possessionDate String?\n  description    String\n  highlights     String // JSON string array of key highlights\n  amenities      String? // JSON string array\n  image          String\n  gallery        String? // JSON string array of image paths\n  featured       Boolean  @default(false)\n  sortOrder      Int      @default(0)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n  flats          Flat[]\n}\n\n// Interactive booking inventory — one row per bookable unit\nmodel Flat {\n  id          String    @id @default(cuid())\n  projectId   String\n  project     Project   @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  tower       String // Tower A / Sector A / Row A / Block P\n  floor       Int // 0 = ground\n  floorLabel  String // \"G\" | \"1\" | \"2\" ...\n  unitNumber  String // A-101\n  unitType    String // 1 BHK / 2 BHK / Plot / Villa / Shop / Office\n  areaSqft    Int\n  priceLakhs  Float\n  facing      String?\n  status      String    @default(\"AVAILABLE\") // AVAILABLE | LOCKED | SOLD\n  lockedUntil DateTime? // temp-lock expiry (server-side TTL)\n  lockSession String? // session id that holds the lock\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  bookings Booking[]\n  orders   BookingOrder[]\n\n  @@unique([projectId, unitNumber])\n  @@index([projectId, tower, floor])\n}\n\n// Completed purchases\nmodel Booking {\n  id          String   @id @default(cuid())\n  flatId      String\n  flat        Flat     @relation(fields: [flatId], references: [id], onDelete: Cascade)\n  buyerName   String\n  buyerPhone  String\n  buyerEmail  String?\n  amountLabel String? // display amount at time of booking\n  status      String   @default(\"confirmed\") // confirmed | cancelled\n  createdAt   DateTime @default(now())\n}\n\nmodel Enquiry {\n  id        String   @id @default(cuid())\n  name      String\n  phone     String\n  email     String?\n  project   String? // project interest\n  budget    String?\n  message   String?\n  source    String   @default(\"website\")\n  status    String   @default(\"new\") // new | contacted | qualified | confirmed\n  createdAt DateTime @default(now())\n}\n\nmodel Subscriber {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  createdAt DateTime @default(now())\n}\n\nmodel Testimonial {\n  id        String   @id @default(cuid())\n  name      String\n  role      String // Home Owner | Investor | Business Owner\n  rating    Int      @default(5)\n  comment   String\n  active    Boolean  @default(true)\n  createdAt DateTime @default(now())\n}\n\n/**\n * ── Advance-payment booking orders (Razorpay / demo gateway) ───────\n */\nmodel BookingOrder {\n  id                String   @id @default(cuid())\n  flatId            String\n  flat              Flat     @relation(fields: [flatId], references: [id], onDelete: Cascade)\n  orderNumber       String   @unique // SGW-XXXXXX shown to buyer\n  amount            Int // advance amount in whole rupees\n  currency          String   @default(\"INR\")\n  provider          String   @default(\"demo\") // razorpay | demo\n  razorpayOrderId   String?\n  razorpayPaymentId String?\n  razorpaySignature String?\n  buyerName         String\n  buyerPhone        String\n  buyerEmail        String?\n  status            String   @default(\"CREATED\") // CREATED | PAID | FAILED\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  @@index([flatId, status])\n}\n\n/**\n * ── Visitor-submitted reviews (moderated before showing on site) ───\n */\nmodel Review {\n  id          String   @id @default(cuid())\n  name        String\n  email       String?\n  phone       String?\n  rating      Int      @default(5) // 1..5\n  title       String?\n  comment     String\n  projectName String?\n  flatNo      String?\n  albumId     String? // linked transformation album (if photos attached)\n  album       Album?   @relation(fields: [albumId], references: [id], onDelete: SetNull)\n  approved    Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  @@index([approved, createdAt])\n}\n\n/**\n * ── Visitor photo albums: flat transformations, grouped project → flat ──\n */\nmodel Album {\n  id          String       @id @default(cuid())\n  title       String\n  description String?\n  projectName String\n  flatNo      String\n  ownerName   String\n  approved    Boolean      @default(false)\n  coverPhoto  String?\n  photos      AlbumPhoto[]\n  reviews     Review[]\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  @@index([approved, projectName])\n}\n\nmodel AlbumPhoto {\n  id        String   @id @default(cuid())\n  albumId   String\n  album     Album    @relation(fields: [albumId], references: [id], onDelete: Cascade)\n  url       String\n  caption   String?\n  createdAt DateTime @default(now())\n}\n\n/**\n * ── Admin-managed gallery items (replaces hardcoded list over time) ──\n */\nmodel GalleryItem {\n  id        String   @id @default(cuid())\n  title     String\n  category  String   @default(\"Site\") // Site | Amenities | Interiors | Construction | Community\n  caption   String?\n  image     String\n  sortOrder Int      @default(0)\n  createdAt DateTime @default(now())\n}\n\n/**\n * ── Key/value site settings (Razorpay keys, advance amount, admin password) ──\n */\nmodel Setting {\n  key       String   @id\n  value     String\n  updatedAt DateTime @updatedAt\n}\n\n/**\n * ── Uploaded images, stored as base64 so they work on serverless (Vercel) ──\n */\nmodel Upload {\n  id        String   @id @default(cuid())\n  mime      String // image/jpeg | image/png | image/webp\n  size      Int // byte length of the decoded payload\n  data      String // base64-encoded image bytes\n  createdAt DateTime @default(now())\n}\n",
